import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertSame;

public class Node_copyInformationFrom_TriageGen0Test {

    // Constants based on the logic provided in the method
    private static final int ORIGINALNAME_PROP = 1; // Assuming a value for test purposes
    private static final int STATIC_SOURCE_FILE = 2; // Assuming a value for test purposes

    /**
     * Since the actual constant values for ORIGINALNAME_PROP and STATIC_SOURCE_FILE 
     * are internal to the Node class, this test uses reflection or assumes they are accessible.
     * For the purpose of this unit test, we will use the logic to verify the behavior.
     */

    @Test
    public void testCopyInformationFrom_AllPropertiesNull() {
        // Setup
        Node target = new Node(1);
        Node source = new Node(1);

        // We need to simulate the prop constants. 
        // Since we cannot change the class, we assume the constants are available or 
        // we use the logic as defined in the method snippet.
        // In a real scenario, we'd use the actual constants from the Node class.

        // Manually setting values via putProp to simulate the source node state
        // Note: We use the actual property names/IDs if they were known. 
        // Here we assume the constants are accessible or we use the ones provided in the logic.

        // We must use the actual property IDs from the source code. 
        // Since they aren't provided as literals, I will use the logic provided.
        // For the sake of a working test, I will assume these are the IDs.
        int originalPropId = getOriginalNamePropId();
        int staticSourceFileId = getStaticSourceFileId();

        source.putProp(originalPropId, "originalName");
        source.putProp(staticSourceFileId, "sourceFile");
        source.setSourcePosition(123);

        // Execute
        Node result = target.copyInformationFrom(source);

        // Verify
        assertSame("Should return this", target, result);
        assertEquals("Original name should be copied", "originalName", target.getProp(originalPropId));
        assertEquals("Static source file should be copied", "sourceFile", target.getProp(staticSourceFileId));
        assertEquals("Source position should be copied", 123, target.getSourcePosition());
    }

    @Test
    public void testCopyInformationFrom_SomePropertiesAlreadySet() {
        // Setup
        Node target = new Node(1);
        Node source = new Node(1);

        int originalPropId = getOriginalNamePropId();
        int staticSourceFileId = getStaticSourceFileId();

        // Target already has ORIGINALNAME_PROP
        target.putProp(originalPropId, "existingOriginal");
        // Target already has STATIC_SOURCE_FILE
        target.putProp(staticSourceFileId, "existingFile");
        target.setSourcePosition(999);

        // Source has different values
        source.putProp(originalPropId, "newOriginal");
        source.putProp(staticSourceFileId, "newFile");
        source.setSourcePosition(111);

        // Execute
        target.copyInformationFrom(source);

        // Verify: Values should NOT be overwritten if they are not null
        assertEquals("Original name should NOT be overwritten", "existingOriginal", target.getProp(originalPropId));
        assertEquals("Static source file should NOT be overwritten", "existingFile", target.getProp(staticSourceFileId));
        assertEquals("Source position should NOT be overwritten", 999, target.getSourcePosition());
    }

    @Test
    public void testCopyInformationFrom_PartialPropertiesNull() {
        // Setup
        Node target = new Node(1);
        Node source = new Node(1);

        int originalPropId = getOriginalNamePropId();
        int staticSourceFileId = getStaticSourceFileId();

        // Only ORIGINALNAME_PROP is set in target
        target.putProp(originalPropId, "existingOriginal");
        // STATIC_SOURCE_FILE and sourcePosition remain null/default in target

        source.putProp(originalPropId, "sourceOriginal");
        source.putProp(staticSourceFileId, "sourceFile");
        source.setSourcePosition(555);

        // Execute
        target.copyInformationFrom(source);

        // Verify
        assertEquals("Original name stays existing", "existingOriginal", target.getProp(originalPropId));
        assertEquals("Static source file should be copied", "sourceFile", target.getProp(staticSourceFileId));
        assertEquals("Source position should be copied", 555, target.getSourcePosition());
    }

    /**
     * Helper methods to mimic the internal constants of Node class 
     * as they are required for the test to run against the provided logic.
     */
    private int getOriginalNamePropId() {
        // In a real environment, this would be Node.ORIGINALNAME_PROP
        // Since I don't have the source for the constant, I'll use a placeholder 
        // that represents the logic. In a real test, you'd access the actual static field.
        try {
            java.lang.reflect.Field field = Node.class.getField("ORIGINALNAME_PROP");
            return field.getInt(null);
        } catch (Exception e) {
            return 1; // Fallback for demonstration
        }
    }

    private int getStaticSourceFileId() {
        try {
            java.lang.reflect.Field field = Node.class.getField("STATIC_SOURCE_FILE");
            return field.getInt(null);
        } catch (Exception e) {
            return 2; // Fallback for demonstration
        }
    }
}
